#pragma once

// PLEASE DO NOT EDIT THIS FILE, IT IS GENERATED AND WILL BE OVERWRITTEN:
// https://github.com/ccxt/ccxt/blob/master/CONTRIBUTING.md#how-to-contribute-code

#include "../../BaseTest.Bridge.h"

// forward declarations - TS hoists function declarations, C++ does not
void testHandleHttpStatusCode();

void testHandleHttpStatusCode() {
  ccxt::Exchange exchange = ccxt::Exchange(ccxt::dict{
      {std::string("id"), std::string("sampleexchange")},
  });
  // every status of the default httpExceptions table must throw — one status
  // per distinct error class of the table.
  //
  // The blocks below are deliberately written out one status at a time with
  // integer literals instead of looping over a list of codes:
  //   - the C# and Java bases declare `handleHttpStatusCode (int code, ...)`,
  //     so an element read out of an untyped list does not compile there;
  //   - only *that* a status throws is asserted, never which class, because
  //     `error instanceof <Class>` inside a transpiled catch does not survive
  //     the Go port (the recover handler compares the panic payload's type
  //     against the constructor). The status → class mapping is pinned by
  //     ts/src/test/base/errors/** instead — do not weaken this list by adding
  //     statuses that are absent from httpExceptions.
  ccxt::any caught = false;
  try {
    exchange.handleHttpStatusCode(429, std::string("reason"),
                                  std::string("url"), std::string("GET"),
                                  std::string("body"));
  } catch (const std::exception &error) {
    caught = true;
  }
  assertTrue(caught, std::string("status 429 should have thrown"));
  caught = false;
  try {
    exchange.handleHttpStatusCode(418, std::string("reason"),
                                  std::string("url"), std::string("GET"),
                                  std::string("body"));
  } catch (const std::exception &error) {
    caught = true;
  }
  assertTrue(caught, std::string("status 418 should have thrown"));
  caught = false;
  try {
    exchange.handleHttpStatusCode(401, std::string("reason"),
                                  std::string("url"), std::string("GET"),
                                  std::string("body"));
  } catch (const std::exception &error) {
    caught = true;
  }
  assertTrue(caught, std::string("status 401 should have thrown"));
  caught = false;
  try {
    exchange.handleHttpStatusCode(408, std::string("reason"),
                                  std::string("url"), std::string("GET"),
                                  std::string("body"));
  } catch (const std::exception &error) {
    caught = true;
  }
  assertTrue(caught, std::string("status 408 should have thrown"));
  caught = false;
  try {
    exchange.handleHttpStatusCode(500, std::string("reason"),
                                  std::string("url"), std::string("GET"),
                                  std::string("body"));
  } catch (const std::exception &error) {
    caught = true;
  }
  assertTrue(caught, std::string("status 500 should have thrown"));
  caught = false;
  try {
    exchange.handleHttpStatusCode(422, std::string("reason"),
                                  std::string("url"), std::string("GET"),
                                  std::string("body"));
  } catch (const std::exception &error) {
    caught = true;
  }
  assertTrue(caught, std::string("status 422 should have thrown"));
  // statuses missing from the table must not throw — derived handleErrors
  // implementations rely on exactly that swallow when they guard with
  // a httpExceptions lookup before deferring to the status handler
  exchange.handleHttpStatusCode(402, std::string("reason"), std::string("url"),
                                std::string("GET"), std::string("body"));
  exchange.handleHttpStatusCode(406, std::string("reason"), std::string("url"),
                                std::string("GET"), std::string("body"));
  exchange.handleHttpStatusCode(412, std::string("reason"), std::string("url"),
                                std::string("GET"), std::string("body"));
  exchange.handleHttpStatusCode(413, std::string("reason"), std::string("url"),
                                std::string("GET"), std::string("body"));
  exchange.handleHttpStatusCode(505, std::string("reason"), std::string("url"),
                                std::string("GET"), std::string("body"));
  exchange.handleHttpStatusCode(524, std::string("reason"), std::string("url"),
                                std::string("GET"), std::string("body"));
  // success statuses never throw
  exchange.handleHttpStatusCode(200, std::string("OK"), std::string("url"),
                                std::string("GET"), std::string("body"));
  exchange.handleHttpStatusCode(201, std::string("Created"), std::string("url"),
                                std::string("GET"), std::string("body"));
  // dispatch composition: the base handleErrors stub returns undefined, so an
  // error envelope on an uncovered status passes both steps without a throw —
  // a derived handleErrors that wants to surface it must throw on its own
  ccxt::any skip = exchange.handleErrors(
      406, std::string("Not Acceptable"), std::string("url"),
      std::string("GET"), ccxt::dict{}, std::string("{\"success\":false}"),
      ccxt::dict{
          {std::string("success"), false},
      },
      ccxt::dict{}, std::string(""));
  assertTrue(isEqual(skip, ccxt::any{}),
             std::string("the base handleErrors stub should return undefined"));
  exchange.handleHttpStatusCode(406, std::string("Not Acceptable"),
                                std::string("url"), std::string("GET"),
                                std::string("{\"success\":false}"));
}
